// Keeps generated package files in step with what is on disk, so adding a component or a
// stylesheet needs no manual wiring:
//   src/styles/index.css  <- an @import for every file in styles/base, styles/layout, styles/components
//
// `node scripts/sync.mjs`          rewrites the generated files
// `node scripts/sync.mjs --check`  exits 1 if they are out of date (used by the tests)
//
// Components, layouts and lib modules need no registration: `exports` in package.json uses wildcards.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import process from 'node:process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const STYLES = join(ROOT, 'src/styles');
// tokens first, then element defaults, page chrome, components. Order inside a folder is alphabetical.
const GROUPS = ['base', 'layout', 'components'];
// Within base/, tokens must come before everything else.
const first = (group) => (group === 'base' ? ['tokens.css'] : []);

export function expectedIndexCss() {
  const imports = GROUPS.flatMap((group) => {
    const files = readdirSync(join(STYLES, group))
      .filter((f) => f.endsWith('.css'))
      .sort();
    const ordered = [
      ...first(group).filter((f) => files.includes(f)),
      ...files.filter((f) => !first(group).includes(f)),
    ];
    return ordered.map((f) => `@import './${group}/${f}';`);
  });
  return (
    '/* GENERATED by scripts/sync.mjs (npm run ui:sync): one @import per stylesheet in base/, layout/ and\n' +
    '   components/. Edit those files, not this one. Import `@zkevinly/ui/styles` to get everything. */\n\n' +
    imports.join('\n') +
    '\n'
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = join(STYLES, 'index.css');
  const next = expectedIndexCss();
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    /* missing: will be written */
  }
  if (process.argv.includes('--check')) {
    if (current !== next) {
      process.stderr.write(
        'packages/ui/src/styles/index.css is out of date. Run: npm run ui:sync\n',
      );
      process.exit(1);
    }
  } else if (current !== next) {
    writeFileSync(target, next);
    process.stdout.write('Updated src/styles/index.css\n');
  }
}
